static const Question *const LEVELS[N_LEVELS] = {
  L0, L1, L2, L3, L4, L5, L6, L7, L8, L9, L10, L11, L12, L13, L14
};

static const int LEVEL_N[N_LEVELS] = {
  28, 28, 28, 27, 27, 30, 27, 30, 27, 27, 26, 26, 26, 26, 26
};

int questions_count(int level) {
  if (level < 0 || level >= N_LEVELS) return 0;
  return LEVEL_N[level];
}

const Question *questions_get(int level, int index) {
  if (level < 0 || level >= N_LEVELS) return 0;
  if (index < 0 || index >= LEVEL_N[level]) return 0;
  return &LEVELS[level][index];
}

int questions_min_count(void) {
  int i, m = LEVEL_N[0];
  for (i = 1; i < N_LEVELS; i++) {
    if (LEVEL_N[i] < m) m = LEVEL_N[i];
  }
  return m;
}
